import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.BqDA2HS7.js";const u=JSON.parse('{"title":"Stage · 阶段","description":"","frontmatter":{},"headers":[],"relativePath":"strategies/stage.md","filePath":"strategies/stage.md"}'),o={name:"strategies/stage.md"};function l(s,a,d,n,h,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="stage-·-阶段" tabindex="-1">Stage · 阶段 <a class="header-anchor" href="#stage-·-阶段" aria-label="Permalink to &quot;Stage · 阶段&quot;">​</a></h1><p>Stage 从高效模型开始，根据新增的可信执行证据选择下一轮模型。 它调整模型调用，不规划 DAG，也不替接入方执行工具。</p><h2 id="规则模式" tabindex="-1">规则模式 <a class="header-anchor" href="#规则模式" aria-label="Permalink to &quot;规则模式&quot;">​</a></h2><p>默认窗口为最近 3 条有效工具结果，判断阈值为 0.5，接管保持 2 次执行。 “两次”包含触发切换的当前调用和下一次调用。</p><ol><li>工具结果或模型用量未确认，停止后续受管调用。</li><li>出现新的同类可信重复失败，切换到指定强执行角色。</li><li>保持期内继续使用该角色。</li><li>有新证据时计算规则信号；保持结束且无新困难时恢复高效角色。</li><li>没有有效信号时使用高效角色；旧事件不重复触发。</li></ol><p>单次合理测试失败、正常搜索、权限拒绝和基础设施故障不等于模型能力不足。 失败指纹必须关联工具、规范化参数和可信失败信息，不能仅比较错误码。</p><h2 id="规则与-jev-如何协作" tabindex="-1">规则与 Jev 如何协作 <a class="header-anchor" href="#规则与-jev-如何协作" aria-label="Permalink to &quot;规则与 Jev 如何协作&quot;">​</a></h2><p>可选协作模式在受控边界询问本地结构化 Judge 或官方 Jev。 规则处理工具事实、去重、安全和保持；Judge 提供有限回答信号，Python 决定最终动作。 它不会为每条模糊文字无限增加判别链条。</p><p>协作参数包括判别间隔、每任务判别批次上限、保持和降回确认次数。 该模式保留实验标识；超时或后端崩溃停止，不自动切换云端或重发。</p><h2 id="必要设置" tabindex="-1">必要设置 <a class="header-anchor" href="#必要设置" aria-label="Permalink to &quot;必要设置&quot;">​</a></h2><p>高效、强执行模型与各自推理等级；规则参数；协作模式另选择 Judge、数据域及期限。 两个角色绑定相同模型与参数时可按准入运行，但不会产生实际模型切换。</p><h2 id="工具证据的来源" tabindex="-1">工具证据的来源 <a class="header-anchor" href="#工具证据的来源" aria-label="Permalink to &quot;工具证据的来源&quot;">​</a></h2><p>DSH 原生事件能携带结构化工具结果。纯 Base URL 的普通文本结果往往没有可信退出状态， 会记为 <code>unclassified</code>。Codex CLI 的可选证据适配另见<a href="./../integrations/codex.html">接入说明</a>。 Router 不从正文“成功／失败”猜测退出状态。</p><h2 id="轨迹应该看到什么" tabindex="-1">轨迹应该看到什么 <a class="header-anchor" href="#轨迹应该看到什么" aria-label="Permalink to &quot;轨迹应该看到什么&quot;">​</a></h2><p>证据 ID、评分、重复失败／保持／恢复原因、保持前后计数、实际模型、推理等级与费用。 规则模式应没有额外 Judge 调用；协作模式记录实际 Judge 批次、原始答案和实验状态。</p>',15)])])}const _=e(o,[["render",l]]);export{u as __pageData,_ as default};
